#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_deleteNode_node_with_two_children(void) {
    // Build a tree where the node to delete has two children.
    // Example tree: root=50, left=30, right=70, and 70 has left=60, right=80.
    // Deleting 50 will trigger the two‑child case (path 6).
    int values[] = {50, 30, 70, 60, 80};
    struct node* root = helper_build_tree(values, 5);

    // Verify the tree contains the key 50 before deletion.
    // (We assume helper_assert_tree_contains is available per operation map.)
    // Since helper_assert_tree_contains is not a standard Unity macro,
    // we perform a simple search manually.
    // Instead, we can rely on the fact that helper_build_tree succeeded.
    // We'll use inorder traversal after deletion to confirm the key is gone.

    // Capture inorder before deletion for sanity (optional).
    // Actually, we just need to ensure the deletion happens correctly.

    // Execute deletion of the root (key 50) which has two children.
    struct node* new_root = deleteNode(root, 50);

    // Assertions:
    // 1. The returned root should not be NULL (tree still exists).
    TEST_ASSERT_NOT_NULL(new_root);
    // 2. The new root should not contain the key 50.
    // We can use helper_assert_tree_not_contains if we trust it, but
    // to be safe we write a simple search.
    // Since helper_assert_tree_not_contains is listed as created, we use it.
    helper_assert_tree_not_contains(new_root, 50);
    // 3. The tree should still contain the other keys.
    // We can verify by checking that the inorder traversal is correct.
    // After deleting 50, the new root becomes 60 (the inorder successor).
    // Expected inorder: 30 60 70 80
    helper_assert_tree_inorder(new_root, "30 60 70 80 ");

    // Cleanup
    helper_free_tree(new_root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_deleteNode_node_with_two_children);
    return UNITY_END();
}

